"""Reusable conversions for legacy Meridian CRM storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == "00000000":
        return None

    parsed = date(int(yyyymmdd[:4]), int(yyyymmdd[4:6]), int(yyyymmdd[6:8]))
    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD representation."""
    if iso is None or iso == "":
        return "00000000"

    parsed = date.fromisoformat(iso)
    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N flag, where blank means N."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to integer currency minor units."""
    if amount is None or amount == "":
        return 0

    exponent = 0 if currency == "JPY" else 2
    scaled = Decimal(str(amount)) * (Decimal(10) ** exponent)
    return int(scaled.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
